class Solution:
    def maxProduct(self, nums: list[int]) -> int:
        a = sorted(nums)
        max_pair = max(a[0] * a[1], a[-1] * a[-2])
        min_pair = min(a[0] * a[1], a[0] * a[-1])
        return 100000 * max(abs(max_pair), abs(min_pair))

