class Solution {
public:
    long long maxProduct(vector<int>& nums) {
        vector<long long> a(nums.begin(), nums.end());
        sort(a.begin(), a.end());
        long long mx = max(a[0]*a[1], a[a.size()-1]*a[a.size()-2]);
        long long mn = min(a[0]*a[1], a[0]*a[a.size()-1]);
        return 100000LL * max(llabs(mx), llabs(mn));
    }
};

