class Solution {
    public long maxProduct(int[] nums) {
        long[] a = new long[nums.length];
        for (int i = 0; i < nums.length; i++) a[i] = nums[i];
        java.util.Arrays.sort(a);
        int n = a.length;
        long mx = Math.max(a[0]*a[1], a[n-1]*a[n-2]);
        long mn = Math.min(a[0]*a[1], a[0]*a[n-1]);
        return 100000L * Math.max(Math.abs(mx), Math.abs(mn));
    }
}

