class Solution:
    def maxProduct(self, nums: list[int]) -> int:
        mx = [-float('inf')] * 3
        mn = [float('inf')] * 2
        for x in nums:
            if x > mx[0]: mx = [x, mx[0], mx[1]]
            elif x > mx[1]: mx = [mx[0], x, mx[1]]
            elif x > mx[2]: mx[2] = x
            if x < mn[0]: mn = [x, mn[0]]
            elif x < mn[1]: mn[1] = x
        max_pair = max(mx[0] * mx[1], mn[0] * mn[1])
        min_pair = min(mn[0] * mn[1], mn[0] * mx[0])
        return 100000 * max(abs(max_pair), abs(min_pair))

